import parse_kv

def test_parse_kv():
    assert parse_kv.parse_kv('') == {}
    assert parse_kv.parse_kv('key1=value1; key2=value2') == {'key1': 'value1', 'key2': 'value2'}
    assert parse_kv.parse_kv('key;escaped\;semicolon=value;with\;semicolon') == {'key;escaped;semicolon': 'value;with;semicolon'}
    assert parse_kv.parse_kv('  key_with_leading_space = value_with_trailing_space  ') == {'key_with_leading_space': 'value_with_trailing_space'}
    assert parse_kv.parse_kv('multiple;values;in;one;key=value') == {'multiple': 'value', 'values': 'in', 'in': 'one', 'one': 'key=value'}
    # Edge case: only escaped semicolon
    assert parse_kv.parse_kv('only_escaped\\;semicolon=here') == {'only_escaped;semicolon': 'here'}
    # Edge case: trailing semicolon
    assert parse_kv.parse_kv('key=value;') == {'key': 'value'}
    # Edge case: leading semicolon
    assert parse_kv.parse_kv(';key=value') == {'key': 'value'}
    # Edge case: multiple spaces
    assert parse_kv.parse_kv('  key  =  value  ') == {'key': 'value'}
    # Edge case: backslash not followed by semicolon
    assert parse_kv.parse_kv('no_escape=here\\') == {'no_escape': 'here\\'}
    print('All tests passed')

